// ─── THOUSANDS SEPARATOR ─────────────────────────────────────
const formatThousands = (s) => {
  if (!s) return '';
  return s.replace(/[^0-9]/g, '').replace(/\B(?=(\d{3})+(?!\d))/g, '.');
};

// ─── SVG FILTER ICON ─────────────────────────────────────────
function FilterSvgIcon({ size = 26, active = false }) {
  const c = active ? '#43A047' : '#444';
  return (
    <Svg width={size} height={size * 1.9} viewBox="0 0 24 46" fill="none">
      <Rect x="9" y="0" width="6" height="7" rx="1.5" stroke={c} strokeWidth="1.8" fill="none"/>
      <Rect x="2" y="7" width="20" height="28" rx="3" stroke={c} strokeWidth="1.8" fill="none"/>
      <Line x1="7"  y1="11" x2="7"  y2="31" stroke={c} strokeWidth="1.5" strokeLinecap="round"/>
      <Line x1="10" y1="11" x2="10" y2="31" stroke={c} strokeWidth="1.5" strokeLinecap="round"/>
      <Line x1="13" y1="11" x2="13" y2="31" stroke={c} strokeWidth="1.5" strokeLinecap="round"/>
      <Line x1="16" y1="11" x2="16" y2="31" stroke={c} strokeWidth="1.5" strokeLinecap="round"/>
      <Line x1="19" y1="11" x2="19" y2="31" stroke={c} strokeWidth="1.5" strokeLinecap="round"/>
      <Rect x="9" y="35" width="6" height="7" rx="1.5" stroke={c} strokeWidth="1.8" fill="none"/>
    </Svg>
  );
}

