// Ö-2: Statik araçlara createdAt ekle (Bugün Eklenenler çalışsın)
CARS.forEach((car, i) => {
  if (!car.createdAt) {
    const offset = i % 4 === 0 ? 0 : i % 4 === 1 ? 0 : i % 4 === 2 ? 1 : 2;
    const d = new Date(); d.setDate(d.getDate() - offset);
    d.setHours(8 + (i % 12), (i * 7) % 60, 0, 0);
    car.createdAt = d.getTime();
  }
});

// ─── YARDIMCI FONKSİYONLAR ────────────────────────────────────
const parseNum = (s) => parseInt((s||'0').replace(/[^0-9]/g,'')) || 0;
const fmtPrice = (s) => s ? formatThousands(String(s)) + ' ₺' : '';
const fmtKm    = (s) => s ? formatThousands(String(s)) + ' km' : '';

function applyFiltersToList(list, f, userLocation) {
  // İlan numarasıyla arama: doluysa diğer tüm filtreleri atla, sadece tam eşleşen
  // ilanı göster (sahibinden.com vb. sitelerdeki "ilan no ile ara" mantığıyla aynı).
  if (f.ilanNo && String(f.ilanNo).trim()) {
    const q = String(f.ilanNo).trim();
    return list.filter(car => String(car.ilanNo || '').includes(q));
  }
  return list.filter(car => {
    if (f.keyword && f.keyword.trim()) {
      const q = f.keyword.trim().toLowerCase();
      const haystack = [car.brand,car.model,car.city,car.district,car.description,car.engine,car.color,car.fuel,car.body]
        .filter(Boolean).join(' ').toLowerCase();
      if (!haystack.includes(q)) return false;
    }
    if (f.city && car.city !== f.city) return false;
    if (f.district && car.district !== f.district) return false;
    if (f.vasitaTuru && car.vasitaTuru !== f.vasitaTuru) return false;
    if (f.brand && car.brand !== f.brand) return false;
    if (f.model && car.model !== f.model) return false;
    if (f.engine && car.engine !== f.engine) return false;
    if (f.yearFrom && parseInt(car.year) < parseInt(f.yearFrom)) return false;
    if (f.yearTo   && parseInt(car.year) > parseInt(f.yearTo))   return false;
    if (f.kmMin    && parseNum(car.km)    < parseNum(f.kmMin))    return false;
    if (f.kmMax    && parseNum(car.km)    > parseNum(f.kmMax))    return false;
    if (f.priceMin && parseNum(car.price) < parseNum(f.priceMin)) return false;
    if (f.priceMax && parseNum(car.price) > parseNum(f.priceMax)) return false;
    if (f.fuel.length         && !f.fuel.includes(car.fuel))                 return false;
    if (f.transmission.length && !f.transmission.includes(car.transmission)) return false;
    if (f.body.length         && !f.body.includes(car.body))                 return false;
    if (f.damage.length       && !f.damage.includes(car.damage))             return false;
    if (f.sellerType.length   && !f.sellerType.includes(car.sellerType))     return false;
    if (f.cekis.length        && !f.cekis.includes(car.cekis))               return false;
    if (f.aracDurumu.length   && !f.aracDurumu.includes(car.aracDurumu))     return false;
    if (f.takas               && car.takas !== f.takas)                       return false;
    if (f.hp.length           && !f.hp.includes(car.hp))                     return false;
    if (f.engineCC.length) {
      const cc = Math.round(parseFloat(car.engine) * 1000);
      if (!isNaN(cc) && cc > 0) {
        const inRange = f.engineCC.some(r => {
          if (r.includes('kadar')) return cc <= 1300;
          if (r.includes('üzeri')) return cc > 6000;
          const m = r.match(/(\d+)-(\d+)/);
          return m ? cc >= parseInt(m[1]) && cc <= parseInt(m[2]) : false;
        });
        if (!inRange) return false;
      }
    }
    // Mesafe filtresi (konum aktifse)
    if (userLocation && f.distance && f.distance !== 'Tüm Türkiye') {
      const maxKm = parseInt(f.distance);
      if (!isNaN(maxKm)) {
        const carCoords = SEHIR_COORDS[car.city];
        if (carCoords) {
          const dist = haversine(userLocation.lat, userLocation.lng, carCoords.lat, carCoords.lng);
          if (dist > maxKm) return false;
        }
      }
    }
    return true;
  });
}

function countActiveFilters(f) {
  let n = 0;
  if (f.city) n++;
  if (f.distance !== '1 km' && f.distance !== 'Tüm Türkiye') n++;
  if (f.brand) n++;
  if (f.yearFrom || f.yearTo) n++;
  if (f.kmMin || f.kmMax) n++;
  if (f.priceMin || f.priceMax) n++;
  n += f.fuel.length + f.transmission.length + f.body.length + f.damage.length + f.sellerType.length + f.cekis.length + f.aracDurumu.length + f.hp.length + f.engineCC.length;
  return n;
}

// ─── AppTextInput ─────────────────────────────────────────────
function AppTextInput(props) {
  return <TextInput {...props} />;
}

// ─── Numeric klavye takip sistemi ─────────────────────────────
// KbDismissBtn'i yalnızca numeric input odaklanınca gösterir.
const _numericListeners = new Set();
let _numericActive = false;
function _setNumericActive(val) {
  _numericActive = val;
  _numericListeners.forEach(fn => fn(val));
}
// Numeric input'a sarmalayıcı — focus/blur otomatik bildirir
// skipTracking=true verilirse KbDismissBtn tetiklenmez (filtre ekranı gibi yerlerde)
function NumericInput({ skipTracking, ...props }) {
  return (
    <TextInput
      {...props}
      onFocus={e => { if (!skipTracking) _setNumericActive(true);  props.onFocus?.(e); }}
      onBlur={e  => { if (!skipTracking) _setNumericActive(false); props.onBlur?.(e);  }}
    />
  );
}

// ─── KLAVYE YÜKSEKLİĞİ HOOK (her screen'de scroll padding için) ───
function useKbPad() {
  const [pad, setPad] = useState(0);
  useEffect(() => {
    const show = Keyboard.addListener(
      Platform.OS === 'ios' ? 'keyboardWillShow' : 'keyboardDidShow',
      e => setPad(e.endCoordinates.height)
    );
    const hide = Keyboard.addListener(
      Platform.OS === 'ios' ? 'keyboardWillHide' : 'keyboardDidHide',
      () => setPad(0)
    );
    return () => { show.remove(); hide.remove(); };
  }, []);
  return pad;
}

// ─── PROFİL ANALİTİK GRAFİĞİ ────────────────────────────────

// ─── KLAVYE KAPAT BUTONU (tüm ekranlar — klavye açıkken sağ üst köşe) ────
// Klavye açılınca klavyenin sağ üst köşesinde dairesel aşağı ok butonu gösterir.
function KbDismissBtn() {
  const [kbHeight, setKbHeight] = useState(0);
  const [numericActive, setNumericActive] = useState(false);
  const hideTimer = useRef(null);
  useEffect(() => {
    // numeric focus takibi
    _numericListeners.add(setNumericActive);
    setNumericActive(_numericActive);
    return () => _numericListeners.delete(setNumericActive);
  }, []);
  useEffect(() => {
    const show = Keyboard.addListener(
      Platform.OS === 'ios' ? 'keyboardWillShow' : 'keyboardDidShow',
      e => {
        if (hideTimer.current) { clearTimeout(hideTimer.current); hideTimer.current = null; }
        if (Platform.OS === 'android') {
          const navBarH = Math.max(0, Dimensions.get('screen').height - Dimensions.get('window').height);
          setKbHeight(e.endCoordinates.height - navBarH);
        } else {
          setKbHeight(e.endCoordinates.height);
        }
      }
    );
    const hide = Keyboard.addListener(
      Platform.OS === 'ios' ? 'keyboardWillHide' : 'keyboardDidHide',
      () => {
        hideTimer.current = setTimeout(() => { setKbHeight(0); hideTimer.current = null; }, 150);
      }
    );
    return () => { show.remove(); hide.remove(); if (hideTimer.current) clearTimeout(hideTimer.current); };
  }, []);
  if (!kbHeight || !numericActive) return null;
  return (
    <TouchableOpacity
      onPress={Keyboard.dismiss}
      activeOpacity={0.8}
      style={{
        position: 'absolute',
        bottom: kbHeight + 6,
        right: 10,
        zIndex: 9999,
        elevation: 9999,
        width: 38,
        height: 38,
        borderRadius: 19,
        backgroundColor: '#fff',
        alignItems: 'center',
        justifyContent: 'center',
        shadowColor: '#000',
        shadowOpacity: 0.18,
        shadowRadius: 6,
        shadowOffset: { width: 0, height: 2 },
      }}
    >
      <Ionicons name="chevron-down" size={20} color="#333"/>
    </TouchableOpacity>
  );
}
