// Haversine mesafe hesabı (km)
const haversine = (lat1, lng1, lat2, lng2) => {
  const R = 6371;
  const dLat = (lat2 - lat1) * Math.PI / 180;
  const dLng = (lng2 - lng1) * Math.PI / 180;
  const a = Math.sin(dLat/2)**2 + Math.cos(lat1*Math.PI/180)*Math.cos(lat2*Math.PI/180)*Math.sin(dLng/2)**2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
};
const kmLabel = km => km >= KM_MAX ? 'Tüm Türkiye' : `${km} km`;
const kmFromStr = s => { const n = parseInt(s); return isNaN(n) ? KM_MAX : n; };
function DistanceSlider({ value, onChange }) {
  const lang = React.useContext(LangCtx);
  const THUMB = 28;
  const trackWRef = useRef(0);
  const thumbXRef = useRef(0);
  const thumbX = useRef(new Animated.Value(0)).current;
  const curKmRef = useRef(kmFromStr(value));
  const [curKm, setCurKm] = useState(kmFromStr(value));
  const repeatTimer = useRef(null);

  const kmToX = km => ((km - KM_MIN) / (KM_MAX - KM_MIN)) * trackWRef.current;
  const xToKm = x => Math.max(KM_MIN, Math.min(KM_MAX, Math.round(KM_MIN + (x / trackWRef.current) * (KM_MAX - KM_MIN))));

  const applyKm = km => {
    const clamped = Math.max(KM_MIN, Math.min(KM_MAX, km));
    curKmRef.current = clamped;
    setCurKm(clamped);
    if (trackWRef.current > 0) {
      const x = kmToX(clamped);
      thumbXRef.current = x;
      thumbX.setValue(x);
    }
    onChange(kmLabel(clamped));
  };

  const onLayout = e => {
    trackWRef.current = e.nativeEvent.layout.width;
    const x = kmToX(kmFromStr(value));
    thumbXRef.current = x;
    thumbX.setValue(x);
  };

  useEffect(() => {
    const km = kmFromStr(value);
    curKmRef.current = km;
    setCurKm(km);
    if (trackWRef.current > 0) {
      const x = kmToX(km);
      thumbXRef.current = x;
      thumbX.setValue(x);
    }
  }, [value, thumbX]);

  const pan = useRef(PanResponder.create({
    onStartShouldSetPanResponder: () => true,
    onMoveShouldSetPanResponder: () => true,
    onPanResponderGrant: () => {},
    onPanResponderMove: (_, g) => {
      const x = Math.max(0, Math.min(thumbXRef.current + g.dx, trackWRef.current));
      thumbX.setValue(x);
      const km = xToKm(x);
      curKmRef.current = km;
      setCurKm(km);
    },
    onPanResponderRelease: (_, g) => {
      const x = Math.max(0, Math.min(thumbXRef.current + g.dx, trackWRef.current));
      const km = xToKm(x);
      thumbXRef.current = kmToX(km);
      thumbX.setValue(thumbXRef.current);
      curKmRef.current = km;
      setCurKm(km);
      onChange(kmLabel(km));
    },
  })).current;

  const startRepeat = dir => {
    applyKm(curKmRef.current + dir);
    repeatTimer.current = setInterval(() => applyKm(curKmRef.current + dir), 80);
  };
  const stopRepeat = () => { clearInterval(repeatTimer.current); repeatTimer.current = null; };

  return (
    <View style={{ paddingHorizontal: 16, paddingBottom: 12 }}>
      <Text style={{ textAlign: 'center', fontWeight: 'bold', color: '#43A047', fontSize: 16, marginBottom: 14 }}>
        {curKm >= KM_MAX ? (lang==='EN'?'All Turkey':'Tüm Türkiye') : `${curKm} km`}
      </Text>
      <View style={{ flexDirection: 'row', alignItems: 'center' }}>
        {/* Azalt butonu */}
        <TouchableOpacity
          onPress={() => applyKm(curKmRef.current - 1)}
          onLongPress={() => startRepeat(-1)}
          onPressOut={stopRepeat}
          delayLongPress={350}
          style={{ width: 34, height: 34, borderRadius: 17, backgroundColor: '#e0e0e0', alignItems: 'center', justifyContent: 'center', marginRight: 8 }}>
          <Text style={{ fontSize: 20, color: '#555', lineHeight: 22 }}>−</Text>
        </TouchableOpacity>

        {/* Slider */}
        <View style={{ flex: 1, paddingHorizontal: THUMB / 2 }}>
          <View style={{ height: THUMB, justifyContent: 'center' }} onLayout={onLayout}>
            <View style={{ height: 5, backgroundColor: '#e0e0e0', borderRadius: 3, overflow: 'hidden' }}>
              <Animated.View style={{ height: 5, backgroundColor: '#43A047', width: thumbX }} />
            </View>
            <Animated.View {...pan.panHandlers} style={{
              position: 'absolute', width: THUMB, height: THUMB, borderRadius: THUMB / 2,
              backgroundColor: '#43A047', left: Animated.subtract(thumbX, THUMB / 2),
              elevation: 4, shadowColor: '#000', shadowOffset: { width: 0, height: 2 }, shadowOpacity: 0.3, shadowRadius: 3,
            }} />
          </View>
        </View>

        {/* Artır butonu */}
        <TouchableOpacity
          onPress={() => applyKm(curKmRef.current + 1)}
          onLongPress={() => startRepeat(1)}
          onPressOut={stopRepeat}
          delayLongPress={350}
          style={{ width: 34, height: 34, borderRadius: 17, backgroundColor: '#43A047', alignItems: 'center', justifyContent: 'center', marginLeft: 8 }}>
          <Text style={{ fontSize: 20, color: '#fff', lineHeight: 22 }}>+</Text>
        </TouchableOpacity>
      </View>
      <View style={{ flexDirection: 'row', justifyContent: 'space-between', marginTop: 6, paddingHorizontal: 42 }}>
        <Text style={{ fontSize: 10, color: '#999' }}>1 km</Text>
        <Text style={{ fontSize: 10, color: '#999' }}>{lang==='EN'?'All Turkey':'Tüm Türkiye'}</Text>
      </View>
    </View>
  );
}
function ChipRow({ options, selected, onToggle, labelMap }) {
  return (
    <View style={styles.chipRow}>
      {options.map(opt => {
        const active = selected.includes(opt);
        const label = labelMap ? (labelMap[opt]||opt) : opt;
        return (
          <TouchableOpacity key={opt} style={[styles.chip, active && styles.chipActive]} onPress={() => onToggle(opt)}>
            <Text style={[styles.chipText, active && styles.chipTextActive]}>{label}</Text>
          </TouchableOpacity>
        );
      })}
    </View>
  );
}

function OptionList({ title, options, selected, onToggle, labelMap, singleSelect, closeOnSelect = true, onOpen }) {
  const hasActive = Array.isArray(selected) ? selected.length > 0 : !!selected;
  const [open, setOpen] = useState(false);
  const activeLabels = Array.isArray(selected)
    ? selected.map(v => labelMap?.[v]||v).join(', ')
    : (selected ? (labelMap?.[selected]||selected) : '');
  return (
    <View>
      <Text style={styles.filterSection}>{title}</Text>
      <View style={{paddingHorizontal:16}}>
        <TouchableOpacity
          style={styles.miniBox}
          onPress={() => { setOpen(o => { if (!o) onOpen?.(); return !o; }); }}>
          <Text style={hasActive ? styles.miniVal : styles.miniPlaceholder} numberOfLines={1}>
            {hasActive ? activeLabels : 'Seçiniz'}
          </Text>
          <Text style={{color:'#aaa', fontSize:10}}>{open ? '▲' : '▼'}</Text>
        </TouchableOpacity>
        {open && (
          <View style={styles.miniDropdown}>
            <ScrollView style={{maxHeight:200}} nestedScrollEnabled keyboardShouldPersistTaps="handled" showsVerticalScrollIndicator={false}>
              {options.map((opt) => {
                const active = Array.isArray(selected) ? selected.includes(opt) : selected === opt;
                const label  = labelMap ? (labelMap[opt]||opt) : opt;
                return (
                  <TouchableOpacity
                    key={opt}
                    style={[styles.miniItem, {flexDirection:'row', alignItems:'center'}]}
                    onPress={() => { onToggle(opt); if (singleSelect || closeOnSelect) setOpen(false); }}>
                    <Text style={[styles.miniItemText, active && styles.miniItemActive, {flex:1}]}>{label}</Text>
                    {active && <Text style={{color:'#43A047', fontWeight:'bold', fontSize:13}}>✓</Text>}
                  </TouchableOpacity>
                );
              })}
            </ScrollView>
          </View>
        )}
      </View>
    </View>
  );
}

