// ─── SWIPEABLE MATCH CARD ────────────────────────────────────
function SwipeableMatchCard({ car, onPress, onMessage, onDelete, isSold, selectMode, isSelected, onToggleSelect, onSwipeStart, onSwipeEnd, likedPrice, likedAt }) {
  const lang = React.useContext(LangCtx);
  const pan = useRef(new Animated.Value(0)).current;
  const dragRef = useRef(false);
  const wasSwipedRef = useRef(false);
  const responder = PanResponder.create({
    onStartShouldSetPanResponder: () => false,
    onMoveShouldSetPanResponder: (_, g) => !selectMode && Math.abs(g.dx) > Math.abs(g.dy) && Math.abs(g.dx) > 4,
    onMoveShouldSetPanResponderCapture: (_, g) => !selectMode && Math.abs(g.dx) > Math.abs(g.dy) && Math.abs(g.dx) > 4,
    onPanResponderGrant: () => { onSwipeStart && onSwipeStart(); },
    onPanResponderMove: (_, g) => { dragRef.current=true; pan.setValue(Math.max(Math.min(g.dx,12),-120)); },
    onPanResponderRelease: (_, g) => {
      onSwipeEnd && onSwipeEnd();
      if(!dragRef.current) return;
      dragRef.current=false;
      if(g.dx < -18 || g.vx < -0.15) {
        wasSwipedRef.current=true;
        setTimeout(()=>{ wasSwipedRef.current=false; },350);
        Animated.timing(pan,{toValue:-90,duration:100,useNativeDriver:true}).start();
      } else {
        Animated.spring(pan,{toValue:0,useNativeDriver:true}).start();
      }
    },
    onPanResponderTerminate: () => { onSwipeEnd && onSwipeEnd(); dragRef.current=false; },
  });
  const delOpacity = pan.interpolate({inputRange:[-80,-20],outputRange:[1,0],extrapolate:'clamp'});
  return (
    <View style={styles.swipeableWrap}>
      {!selectMode && (
        <Animated.View style={[styles.deleteBack,{opacity:delOpacity}]}>
          <TouchableOpacity style={styles.deleteBtn} onPress={() => {
            Animated.timing(pan,{toValue:-500,duration:250,useNativeDriver:true}).start(()=>onDelete(car.id));
          }}>
            <Text style={styles.deleteIcon}>🗑️</Text>
            <Text style={styles.deleteText}>{lang==='EN'?'Delete':'Sil'}</Text>
          </TouchableOpacity>
        </Animated.View>
      )}
      <Animated.View style={[styles.matchCard,{transform:[{translateX:selectMode?0:pan}]}]} {...(selectMode?{}:responder.panHandlers)}>
        <TouchableOpacity style={[styles.matchCardInner,selectMode&&{paddingLeft:4}]} onPress={selectMode?onToggleSelect:undefined} activeOpacity={selectMode?0.8:1}>
          {selectMode && (
            <View style={{ width:24,height:24,borderRadius:12,borderWidth:2,borderColor:'#43A047',
              alignItems:'center',justifyContent:'center',marginRight:10,
              backgroundColor: isSelected?'#43A047':'#fff' }}>
              {isSelected && <Text style={{color:'#fff',fontSize:14,lineHeight:16}}>✓</Text>}
            </View>
          )}
          <TouchableOpacity onPress={()=>{ if(!wasSwipedRef.current) onPress(); }} activeOpacity={0.8}>
            <Image source={{uri:car.photos?.[0]}} style={styles.matchThumb}/>
            {isSold && <View style={styles.matchSoldBadge}><Text style={styles.matchSoldBadgeText}>{S.soldBadge[lang]}</Text></View>}
          </TouchableOpacity>
          <View style={styles.matchInfo}>
            <Text style={styles.matchName} numberOfLines={1}>{car.brand} {car.model} {car.year}</Text>
            {(()=>{
              const cur = parseFloat(String(car.price).replace(/[^0-9.]/g,''));
              const old = likedPrice ? parseFloat(String(likedPrice).replace(/[^0-9.]/g,'')) : null;
              const diff = old && !isNaN(cur) && !isNaN(old) ? cur - old : 0;
              return (
                <View style={{flexDirection:'row', alignItems:'center', gap:6}}>
                  <Text style={styles.matchPrice} numberOfLines={1}>{fmtPrice(car.price)}</Text>
                  {diff < 0 && <Text style={{fontSize:11,fontWeight:'700',color:'#2e7d32',backgroundColor:'#e8f5e9',borderRadius:6,paddingHorizontal:5,paddingVertical:1}}>▼ {fmtPrice(String(Math.abs(diff)))}</Text>}
                  {diff > 0 && <Text style={{fontSize:11,fontWeight:'700',color:'#E53935',backgroundColor:'#fdecea',borderRadius:6,paddingHorizontal:5,paddingVertical:1}}>▲ {fmtPrice(String(diff))}</Text>}
                </View>
              );
            })()}
            <Text style={styles.matchDetail} numberOfLines={1}>{car.city}{car.district?` / ${car.district}`:''} · {fmtKm(car.km)}</Text>
            {likedAt && <Text style={{fontSize:10,color:'#bbb',marginTop:1}}>📌 {new Date(likedAt).toLocaleDateString('tr-TR',{day:'numeric',month:'short'})}'de beğenildi</Text>}
            {isSold && <Text style={styles.matchSoldLabel}>{lang==='EN'?'Vehicle sold':'Araç satıldı'}</Text>}
          </View>
          {!selectMode && (
            <TouchableOpacity style={styles.msgBtn} onPress={onMessage}>
              <Text style={styles.msgBtnText}>💬</Text>
            </TouchableOpacity>
          )}
        </TouchableOpacity>
      </Animated.View>
    </View>
  );
}

