// ─── PEEK ZOOM (Tinder-style: snap back on release) ───────────
function PeekZoom({ children, style }) {
  const scale = useRef(new Animated.Value(1)).current;
  const dist0 = useRef(null);
  const dist2 = (t) => {
    const dx = t[1].pageX - t[0].pageX;
    const dy = t[1].pageY - t[0].pageY;
    return Math.sqrt(dx * dx + dy * dy);
  };
  const snapBack = () => {
    dist0.current = null;
    Animated.spring(scale, { toValue: 1, useNativeDriver: true, bounciness: 5 }).start();
  };
  return (
    <Animated.View
      style={[style, { transform: [{ scale }] }]}
      onStartShouldSetResponder={(e) => e.nativeEvent.touches.length >= 2}
      onMoveShouldSetResponder={(e) => e.nativeEvent.touches.length >= 2}
      onResponderGrant={(e) => {
        const t = e.nativeEvent.touches;
        if (t.length >= 2) dist0.current = dist2(t);
      }}
      onResponderMove={(e) => {
        const t = e.nativeEvent.touches;
        if (t.length >= 2 && dist0.current) {
          scale.setValue(Math.min(3, Math.max(1, dist2(t) / dist0.current)));
        }
      }}
      onResponderRelease={snapBack}
      onResponderTerminate={snapBack}
    >
      {children}
    </Animated.View>
  );
}

// ─── CARD PEEK ZOOM (discover: photo floats above card on pinch) ──────────
function CardPeekZoom({ uri, style, children }) {
  const scaleAnim = useRef(new Animated.Value(1)).current;
  const dist0 = useRef(null);
  const [zooming, setZooming] = useState(false);
  const dist2 = (t) => {
    const dx = t[1].pageX - t[0].pageX;
    const dy = t[1].pageY - t[0].pageY;
    return Math.sqrt(dx * dx + dy * dy);
  };
  const snapBack = () => {
    dist0.current = null;
    Animated.spring(scaleAnim, { toValue: 1, useNativeDriver: true, bounciness: 6 }).start(() => setZooming(false));
  };
  return (
    <View
      style={style}
      onStartShouldSetResponder={(e) => e.nativeEvent.touches.length >= 2}
      onMoveShouldSetResponder={(e) => e.nativeEvent.touches.length >= 2}
      onResponderGrant={(e) => {
        const t = e.nativeEvent.touches;
        if (t.length >= 2) { dist0.current = dist2(t); scaleAnim.setValue(1); setZooming(true); }
      }}
      onResponderMove={(e) => {
        const t = e.nativeEvent.touches;
        if (t.length >= 2 && dist0.current) {
          scaleAnim.setValue(Math.min(3.5, Math.max(1, dist2(t) / dist0.current)));
        }
      }}
      onResponderRelease={snapBack}
      onResponderTerminate={snapBack}
    >
      {children}
      <Modal visible={zooming} transparent animationType="none" statusBarTranslucent>
        <View style={{ flex: 1, backgroundColor: 'rgba(0,0,0,0.82)', alignItems: 'center', justifyContent: 'center' }}>
          <Animated.Image
            source={{ uri }}
            style={{ width, height: width * 1.35, transform: [{ scale: scaleAnim }] }}
            resizeMode="contain"
          />
        </View>
      </Modal>
    </View>
  );
}

