// ─── SMS SCREEN ───────────────────────────────────────────────
function SmsScreen({ phone, onVerify, onBack, lang }) {
  const [digits, setDigits] = useState(['','','','','','']);
  const refs = [useRef(),useRef(),useRef(),useRef(),useRef(),useRef()];
  const [timer, setTimer] = useState(60);
  const [canResend, setCanResend] = useState(false);
  const timerRef = useRef(null);

  React.useEffect(() => {
    timerRef.current = setInterval(() => {
      setTimer(t => {
        if (t <= 1) { clearInterval(timerRef.current); setCanResend(true); return 0; }
        return t - 1;
      });
    }, 1000);
    return () => clearInterval(timerRef.current);
  }, []);

  const handleResend = () => {
    setTimer(60); setCanResend(false);
    setDigits(['','','','','','']);
    refs[0].current?.focus();
    timerRef.current = setInterval(() => {
      setTimer(t => {
        if (t <= 1) { clearInterval(timerRef.current); setCanResend(true); return 0; }
        return t - 1;
      });
    }, 1000);
  };

  const handleDigit = (val, i) => {
    const d = [...digits];
    d[i] = val.replace(/[^0-9]/g,'').slice(-1);
    setDigits(d);
    if (val && i < 5) refs[i+1].current?.focus();
    if (d.every(x=>x!=='')) setTimeout(onVerify, 300);
  };

  const handleKey = (e, i) => {
    if (e.nativeEvent.key === 'Backspace' && !digits[i] && i > 0) refs[i-1].current?.focus();
  };

  const maskedPhone = phone.length > 6 ? phone.slice(0,3)+'****'+phone.slice(-3) : phone;

  return (
    <KeyboardAvoidingView style={styles.loginContainer} behavior={Platform.OS==='ios'?'padding':'height'}>
      <SafeAreaView style={{flex:1, alignItems:'center'}}>

        <TouchableOpacity onPress={onBack} style={[styles.regBackBtn,{alignSelf:'flex-start',margin:16,flexDirection:'row',alignItems:'center',gap:4}]}>
          <Ionicons name="chevron-back" size={20} color="#43A047"/>
          <Text style={styles.regBackText}>{S.smsBack[lang]}</Text>
        </TouchableOpacity>

        <View style={{flex:1, alignItems:'center', paddingHorizontal:28, width:'100%'}}>
          <Text style={styles.smsIcon}>💬</Text>
          <Text style={styles.smsTitle}>{S.smsTitle[lang]}</Text>
          <Text style={styles.smsSub}>
            <Text style={{color:'#43A047',fontWeight:'700'}}>{maskedPhone}</Text>
            {' '}{S.smsSub[lang]}
          </Text>

          {/* 6 kutu */}
          <View style={styles.smsBoxRow}>
            {digits.map((d,i)=>(
              <AppTextInput
                key={i}
                ref={refs[i]}
                style={[styles.smsBox, d && styles.smsBoxFilled]}
                value={d}
                onChangeText={v=>handleDigit(v,i)}
                onKeyPress={e=>handleKey(e,i)}
                keyboardType="number-pad"
                maxLength={1}
                selectTextOnFocus
                textAlign="center"
              />
            ))}
          </View>

          <TouchableOpacity
            style={[styles.loginBtn,{width:'100%',marginTop:32}]}
            onPress={onVerify} activeOpacity={0.85}>
            <Text style={styles.loginBtnText}>{S.smsVerify[lang]}</Text>
          </TouchableOpacity>

          {canResend ? (
            <TouchableOpacity onPress={handleResend} style={{marginTop:20}}>
              <Text style={styles.smsResendActive}>{S.smsResend[lang]}</Text>
            </TouchableOpacity>
          ) : (
            <Text style={styles.smsResendTimer}>
              {lang==='EN' ? `${S.smsResendIn[lang]} ${timer}s` : `${timer} ${S.smsResendIn[lang]}`}
            </Text>
          )}
        </View>

      </SafeAreaView>
    </KeyboardAvoidingView>
  );
}

// ─── SWIPEABLE LISTING CARD ──────────────────────────────────
function SwipeableListingCard({ car, isSold, onPress, onMarkSold, onUnmarkSold, onDelete, onSwipeStart, onSwipeEnd }) {
  const lang = React.useContext(LangCtx);
  const pan = useRef(new Animated.Value(0)).current;
  const dragRef = useRef(false);
  const delOpacity = pan.interpolate({inputRange:[-80,-20],outputRange:[1,0],extrapolate:'clamp'});
  const responder = PanResponder.create({
    onStartShouldSetPanResponder: () => false,
    onMoveShouldSetPanResponder: (_, g) => Math.abs(g.dx) > Math.abs(g.dy) && Math.abs(g.dx) > 4,
    onMoveShouldSetPanResponderCapture: (_, g) => Math.abs(g.dx) > Math.abs(g.dy) && Math.abs(g.dx) > 4,
    onPanResponderGrant: () => { onSwipeStart && onSwipeStart(); },
    onPanResponderMove: (_, g) => { dragRef.current=true; pan.setValue(Math.max(Math.min(g.dx,12),-120)); },
    onPanResponderRelease: (_, g) => {
      onSwipeEnd && onSwipeEnd();
      if(!dragRef.current) return;
      dragRef.current=false;
      if(g.dx < -18 || g.vx < -0.15) {
        Animated.timing(pan,{toValue:-90,duration:100,useNativeDriver:true}).start();
      } else {
        Animated.spring(pan,{toValue:0,useNativeDriver:true}).start();
      }
    },
    onPanResponderTerminate: () => { onSwipeEnd && onSwipeEnd(); dragRef.current=false; },
  });
  return (
    <View style={{marginBottom:10, position:'relative'}}>
      {/* Delete button behind */}
      <Animated.View style={{position:'absolute',right:0,top:0,bottom:0,width:72,alignItems:'center',justifyContent:'center',opacity:delOpacity}}>
        <TouchableOpacity style={{alignItems:'center',justifyContent:'center',width:72,height:'100%'}}
          onPress={() => Animated.timing(pan,{toValue:-500,duration:250,useNativeDriver:true}).start(()=>onDelete(car.id))}>
          <Text style={{fontSize:28}}>🗑️</Text>
          <Text style={{color:'#f44336',fontSize:12,fontWeight:'700',marginTop:4}}>{lang==='EN'?'Delete':'Sil'}</Text>
        </TouchableOpacity>
      </Animated.View>
      {/* Card */}
      <Animated.View style={{transform:[{translateX:pan}]}} {...responder.panHandlers}>
        <TouchableOpacity style={[styles.myListingCard,{backgroundColor:'#fff',borderRadius:12,padding:10,shadowColor:'#000',shadowOpacity:0.06,shadowRadius:4,elevation:2,borderBottomWidth:0}]}
          activeOpacity={0.85} onPress={onPress}>
          <View style={{position:'relative'}}>
            <Image source={{uri:car.photos?.[0]}} style={styles.myListingThumb}/>
            <View style={styles.myListingTitleOverlay}>
              <Text style={styles.myListingTitleOverlayText}>{S.myListings[lang]}</Text>
            </View>
            {isSold && <View style={styles.myListingSoldOverlay}><Text style={styles.myListingSoldText}>{S.soldBadge[lang]}</Text></View>}
          </View>
          <View style={styles.myListingInfo}>
            <Text style={styles.myListingName} numberOfLines={2}>{car.brand} {car.model} {car.year}</Text>
            <Text style={styles.myListingPrice}>{fmtPrice(car.price)}</Text>
            <Text style={isSold ? styles.myListingStatusSold : styles.myListingStatusActive}>
              {isSold ? S.soldLabel[lang] : S.activeLabel[lang]}
            </Text>
          </View>
          <TouchableOpacity
            style={[styles.soldToggleBtn, isSold && styles.soldToggleBtnActive]}
            onPress={e=>{e.stopPropagation?.(); isSold?onUnmarkSold(car.id):onMarkSold(car.id);}}>
            <Text style={[styles.soldToggleText, isSold && styles.soldToggleTextActive]}>
              {isSold?S.undoSold[lang]:S.markSold[lang]}
            </Text>
          </TouchableOpacity>
        </TouchableOpacity>
      </Animated.View>
    </View>
  );
}

// ─── MY LISTINGS SCREEN ──────────────────────────────────────
// Her ilan için kompakt grafik — car.id seed olarak kullanılır
function ListingAnalytics({ car, lang }) {
  const seed = (car.id || 1);
  const dayLabels = lang === 'EN'
    ? ['M','T','W','T','F','S','S']
    : ['Pt','Sa','Ça','Pe','Cu','Ct','Pz'];
  const today = new Date().getDay();
  // Deterministik sahte veri — seed'e göre
  const days = Array.from({length:7}, (_, i) => {
    const s = (seed * (i+3) * 17) % 100;
    const s2 = (seed * (i+5) * 11) % 100;
    return {
      label: dayLabels[(today - 6 + i + 7) % 7],
      views: Math.floor(s * 0.5) + 2,
      likes: Math.floor(s2 * 0.15),
    };
  });
  const totalV = days.reduce((a,d)=>a+d.views,0);
  const totalL = days.reduce((a,d)=>a+d.likes,0);
  const maxAll = Math.max(...days.map(d=>Math.max(d.views,d.likes)), 1);
  const BAR_H = 48;

  return (
    <View style={{ backgroundColor:'#fff', marginTop:0, marginBottom:12,
      borderBottomLeftRadius:14, borderBottomRightRadius:14,
      paddingHorizontal:12, paddingTop:10, paddingBottom:12,
      borderWidth:1, borderTopWidth:0, borderColor:'#eee' }}>
      {/* Başlık + Toplam */}
      <View style={{ flexDirection:'row', justifyContent:'space-between', alignItems:'center', marginBottom:8 }}>
        <Text style={{ fontSize:11, fontWeight:'700', color:'#555' }}>
          {lang==='EN'?'Last 7 days':'Son 7 gün'}
        </Text>
        <View style={{ flexDirection:'row', gap:10 }}>
          <View style={{ flexDirection:'row', alignItems:'center', gap:3 }}>
            <View style={{ width:7, height:7, borderRadius:4, backgroundColor:'#43A047' }}/>
            <Text style={{ fontSize:10, color:'#43A047', fontWeight:'700' }}>{totalV}</Text>
            <Text style={{ fontSize:10, color:'#888' }}> {lang==='EN'?'views':'görüntü'}</Text>
          </View>
          <View style={{ flexDirection:'row', alignItems:'center', gap:3 }}>
            <View style={{ width:7, height:7, borderRadius:4, backgroundColor:'#E91E63' }}/>
            <Text style={{ fontSize:10, color:'#E91E63', fontWeight:'700' }}>{totalL}</Text>
            <Text style={{ fontSize:10, color:'#888' }}> {lang==='EN'?'likes':'beğeni'}</Text>
          </View>
        </View>
      </View>
      {/* Barlar */}
      <View style={{ flexDirection:'row', alignItems:'flex-end', height: BAR_H + 16 }}>
        {days.map((d, i) => (
          <View key={i} style={{ flex:1, alignItems:'center', justifyContent:'flex-end' }}>
            <View style={{ flexDirection:'row', alignItems:'flex-end', gap:1, height: BAR_H }}>
              <View style={{ width:5, borderRadius:3, backgroundColor:'#43A047',
                height: Math.max(2, (d.views / maxAll) * BAR_H) }}/>
              <View style={{ width:5, borderRadius:3, backgroundColor:'#E91E63',
                height: Math.max(2, (d.likes / maxAll) * BAR_H) }}/>
            </View>
            <Text style={{ fontSize:8, color:'#bbb', marginTop:3 }}>{d.label}</Text>
          </View>
        ))}
      </View>
    </View>
  );
}

